const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const targetDate = ee.Date('2025-09-13');
  const today = ee.Date.now();

  // 2. Data Acquisition & Check - Handle Future Date
  // Check if the target date is in the future. Earth Engine can only process historical data.
  if (targetDate.difference(today, 'day').getInfo() > 0) {
    console.log("The requested date (September 13, 2025) is in the future.");
    console.log("Earth Engine cannot access future satellite imagery to answer this question.");
    console.log("C3"); // Calculation failure because data does not exist yet
    return;
  }

  // --- The following code would be executed if the date was in the past ---

  // Define a rough geometry for Southern British Columbia to check for smoke.
  // This is a simplified bounding box.
  const bcGeometry = ee.Geometry.Rectangle([-125, 48, -114, 52]);

  // Define an approximate location for the Lynx Mountain fire for context (not directly used for detection in BC).
  // This is a point in northeastern Washington near Colville, WA.
  const fireOrigin = ee.Geometry.Point([-117.75, 48.75]);

  // Data Acquisition: Sentinel-5P OFFL L3 Aerosol Index
  // This product is suitable for detecting absorbing aerosols like smoke.
  let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_AER_AI')
    .filterDate(targetDate, targetDate.advance(1, 'day'))
    .filterBounds(bcGeometry);

  const initialSize = collection.size().getInfo();
  if (initialSize === 0) {
    console.log(`No Sentinel-5P images found for ${targetDate.format('YYYY-MM-dd').getInfo()} over British Columbia.`);
    console.log("C1"); // Empty Collection
    return;
  }
  console.log(`Initial images for BC: ${initialSize}`);

  // Filtering for data quality: Use the 'qa_value' band.
  // qa_value > 0.5 is generally recommended for good quality data.
  // Select the Aerosol Index band.
  collection = collection.map(image => image.updateMask(image.select('qa_value').gt(0.5)).select('absorbing_aerosol_index'));

  // Reduce the collection to a single image for the day (e.g., median or mean)
  const dailyImage = collection.median();

  if (!dailyImage) {
    console.log("No valid image after QA filtering.");
    console.log("C2"); // No Valid Pixels (after initial filtering)
    return;
  }

  // Calculate the mean Aerosol Index over British Columbia
  // A higher Aerosol Index value indicates the presence of absorbing aerosols (like smoke).
  const scale = 5000; // Resolution for reduction, to avoid timeout with large geometry
  const meanAI = dailyImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: bcGeometry,
    scale: scale,
    maxPixels: 1e9
  }).get('absorbing_aerosol_index').getInfo();

  if (meanAI === null || isNaN(meanAI)) {
    console.log("Calculation of mean Aerosol Index failed (NaN or None).");
    console.log("C3"); // Calculation Failure
    return;
  }

  // Validate pixel count after all masking and reductions
  const pixelCount = dailyImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: bcGeometry,
    scale: scale,
    maxPixels: 1e9
  }).get('absorbing_aerosol_index').getInfo();

  if (pixelCount === 0) {
    console.log("No valid pixels remain after processing in British Columbia.");
    console.log("C2"); // No Valid Pixels
    return;
  }

  console.log(`Mean Aerosol Index for BC on ${targetDate.format('YYYY-MM-dd').getInfo()}: ${meanAI.toFixed(2)} (Pixels: ${pixelCount})`);

  // Threshold for detecting smoke: Aerosol Index values typically > 0.5 or 1 can indicate significant smoke.
  const smokeThreshold = 0.7; // This is an example threshold, can be adjusted based on typical values for smoke plumes.

  if (meanAI > smokeThreshold) {
    console.log("A"); // Yes, smoke likely spread
  } else {
    console.log("B"); // No, smoke did not significantly spread
  }

}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
